{
  "findings": [
    {
      "check_id": "CKV_AZURE_53",
      "title": "Public network access enabled for MySQL server",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "MEDIUM",
      "explanation": "The resource does not explicitly disable public network access. By default, Azure MySQL servers allow public connections unless `public_network_access_enabled` is set to false or a private endpoint is configured."
    },
    {
      "check_id": "CKV_AZURE_54",
      "title": "MySQL server not enforcing latest TLS version",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "MEDIUM",
      "explanation": "The `minimal_tls_version` attribute is not set. While SSL enforcement is true, the server may accept older, vulnerable TLS versions (e.g., TLS 1.0/1.1) if not explicitly restricted to TLS 1.2 or higher."
    },
    {
      "check_id": "CKV_AZURE_94",
      "title": "Geo-redundant backups not enabled",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "MEDIUM",
      "explanation": "The `geo_redundant_backup_enabled` attribute is missing. Without this, backups are stored locally within the region, increasing risk of data loss in case of regional disaster."
    },
    {
      "check_id": "CKV_AZURE_96",
      "title": "Infrastructure encryption not enabled",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "MEDIUM",
      "explanation": "The `infrastructure_encryption_enabled` attribute is missing. This ensures that the underlying storage infrastructure encrypts data at rest using platform-managed keys, which is a baseline security requirement."
    }
  ],
  "patched_code": "resource \"azurerm_mysql_server\" \"changeme_simple_mysql_server\" {\n  name                = \"changeme-simple-mysql-database-name\"\n  resource_group_name = azurerm_resource_group.changeme_simple_mysql_server_resource_group.name\n  location            = azurerm_resource_group.changeme_simple_mysql_server_resource_group.location\n  storage_mb          = \"5120\"\n  sku_name            = \"B_Gen5_1\"\n  version             = \"8.0\"\n  administrator_login          = \"changemeadmin\"\n  administrator_login_password = \"ch4ng3m3-A@Â£$%^&\"\n  ssl_enforcement_enabled      = true\n  minimal_tls_version          = \"TLS1_2\"\n  public_network_access_enabled = false\n  geo_redundant_backup_enabled  = true\n  infrastructure_encryption_enabled = true\n}",
  "fix_summary": "Added `minimal_tls_version = \"TLS1_2\"` to enforce modern encryption protocols. Set `public_network_access_enabled = false` to restrict access to private networks only. Enabled `geo_redundant_backup_enabled` and `infrastructure_encryption_enabled` to improve resilience and at-rest security compliance."
}
